"""6.7 — plots from committed results, regenerated byte-identically.

    uv run python bench/plots/make_plots.py          # writes bench/plots/*.png
    uv run python bench/plots/make_plots.py --check  # regenerate to a temp dir and compare bytes

Deterministic: fixed figure sizes, no timestamps in PNG metadata, Agg backend.
"""

from __future__ import annotations

import argparse
import json
import sys
import tempfile
from pathlib import Path
from typing import Any

import matplotlib

matplotlib.use("Agg")
import matplotlib.pyplot as plt

ROOT = Path(__file__).resolve().parents[2]
RESULTS = ROOT / "bench" / "results"
OUT = ROOT / "bench" / "plots"
META = {"Software": None, "Creation Time": None}


def _load(kind: str) -> dict[str, Any] | None:
    p = RESULTS / f"{kind}-latest.json"
    return json.loads(p.read_text()) if p.is_file() else None


def residue_by_layer(r: dict[str, Any], out: Path) -> None:
    """Stacked bar: physical residue rate per backend for B0 vs B4."""
    backends = sorted({c["backend"] for c in r["cells"]})

    def rate(b: str, base: str) -> float:
        return next(
            (
                float(c["physical_residue_rate"] or 0.0)
                for c in r["cells"]
                if c["backend"] == b and c["baseline"] == base
            ),
            0.0,
        )

    b0 = [rate(b, "B0") for b in backends]
    b4 = [rate(b, "B4") for b in backends]
    fig, ax = plt.subplots(figsize=(6.4, 3.6), dpi=100)
    x = range(len(backends))
    ax.bar([i - 0.2 for i in x], b0, width=0.4, label="B0 native delete()", color="#c44e52")
    ax.bar([i + 0.2 for i in x], b4, width=0.4, label="B4 Tombstone", color="#4c72b0")
    # A zero bar has no height, and an absent bar and a measured zero look identical — which is
    # exactly the number this chart exists to show. Label every bar with its value.
    for i, (v0, v4) in enumerate(zip(b0, b4, strict=True)):
        for xpos, v in ((i - 0.2, v0), (i + 0.2, v4)):
            ax.annotate(
                f"{v * 100:.1f}%",
                (xpos, v),
                textcoords="offset points",
                xytext=(0, 3),
                ha="center",
                fontsize=8,
            )
    ax.set_xticks(list(x))
    ax.set_xticklabels(backends)
    ax.set_ylim(0, 1.15)
    ax.set_ylabel("physical residue rate")
    ax.set_title("vector bytes still findable after erasure", pad=26)
    # outside the axes: at upper right it sat on top of qdrant's 100% label
    ax.legend(loc="lower center", bbox_to_anchor=(0.5, 1.0), ncol=2, fontsize=8, frameon=False)
    fig.tight_layout()
    fig.savefig(out / "residue-by-layer.png", metadata=META)
    plt.close(fig)


def drift_vs_control(r: dict[str, Any], out: Path) -> None:
    cells = [c for c in r["cells"] if (c.get("drift") or {}).get("n")]
    if not cells:
        return
    labels = [f"{c['backend']}\n{c['baseline']}" for c in cells]
    drift = [c["drift"]["median_drift"] for c in cells]
    ctrl = [c["drift"]["median_control"] for c in cells]
    fig, ax = plt.subplots(figsize=(7.2, 3.6), dpi=100)
    x = range(len(cells))
    ax.bar([i - 0.2 for i in x], drift, width=0.4, label="target deletion drift", color="#c44e52")
    ax.bar([i + 0.2 for i in x], ctrl, width=0.4, label="same-cluster control", color="#8c8c8c")
    ax.set_xticks(list(x))
    ax.set_xticklabels(labels, fontsize=8)
    ax.set_ylabel("median Top-5 centroid drift")
    ax.set_title("Ghost Echoes drift vs control (query budget 5)")
    ax.legend()
    fig.tight_layout()
    fig.savefig(out / "drift-vs-control.png", metadata=META)
    plt.close(fig)


def unlearn_tradeoff(u: dict[str, Any], out: Path) -> None:
    ms = [m for m in u["methods"] if m["name"] in {"M0", "M1", "M2", "M3", "M4"}]
    fig, ax = plt.subplots(figsize=(6.4, 3.6), dpi=100)
    for m in ms:
        ax.scatter(m["holdout_ppl"], m["canary_rate"], s=60)
        ax.annotate(
            m["name"],
            (m["holdout_ppl"], m["canary_rate"]),
            textcoords="offset points",
            xytext=(5, 5),
        )
    ax.set_xlabel("held-out perplexity (lower is better)")
    ax.set_ylabel("canary extraction rate")
    ax.set_ylim(-0.05, 1.05)
    ax.set_title("forgetting vs utility, M0–M4")
    fig.tight_layout()
    fig.savefig(out / "unlearn-tradeoff.png", metadata=META)
    plt.close(fig)
    fig, ax = plt.subplots(figsize=(6.4, 3.2), dpi=100)
    names = [m["name"] for m in ms]
    auc = [m.get("mia", {}).get("loss", {}).get("auc", 0.5) for m in ms]
    lo = [m.get("mia", {}).get("loss", {}).get("ci_low", 0.5) for m in ms]
    hi = [m.get("mia", {}).get("loss", {}).get("ci_high", 0.5) for m in ms]
    ax.errorbar(
        range(len(ms)),
        auc,
        yerr=[
            [a - b for a, b in zip(auc, lo, strict=True)],
            [b - a for a, b in zip(auc, hi, strict=True)],
        ],
        fmt="o",
        capsize=4,
    )
    ax.axhline(0.5, color="#8c8c8c", linestyle="--")
    ax.set_xticks(range(len(ms)))
    ax.set_xticklabels(names)
    ax.set_ylabel("MIA AUC (loss) with 95% CI")
    ax.set_title("membership inference after each method")
    fig.tight_layout()
    fig.savefig(out / "mia-by-method.png", metadata=META)
    plt.close(fig)


def wall_clock(r: dict[str, Any], u: dict[str, Any] | None, out: Path) -> None:
    fig, ax = plt.subplots(figsize=(7.2, 3.6), dpi=100)
    labels = [f"{c['backend']} {c['baseline']}" for c in r["cells"]]
    vals = [c["wall_s_mean"] for c in r["cells"]]
    if u:
        for m in u["methods"]:
            if m["name"] in {"M1", "M2", "M3", "M4"} and m.get("wall_s"):
                labels.append(m["name"])
                vals.append(
                    m["wall_s"] / max(1, u["subjects"]) if m["name"] != "M4" else m["wall_s"]
                )
    ax.barh(range(len(labels)), vals, color="#4c72b0")
    ax.set_yticks(range(len(labels)))
    ax.set_yticklabels(labels, fontsize=7)
    ax.set_xscale("log")
    ax.set_xlabel("seconds per erasure (log)")
    ax.set_title("wall-clock per method")
    fig.tight_layout()
    fig.savefig(out / "wall-clock.png", metadata=META)
    plt.close(fig)


def relearn_curve(u: dict[str, Any], out: Path) -> None:
    rows = u.get("relearn") or []
    if not rows:
        return
    fig, ax = plt.subplots(figsize=(6.4, 3.6), dpi=100)
    methods = sorted({r["method"] for r in rows})
    for m in methods:
        pts = sorted(
            (r["steps"], r["canary_extracted"] / max(1, r["canary_total"]))
            for r in rows
            if r["method"] == m
        )
        ax.plot([p[0] for p in pts], [p[1] for p in pts], marker="o", label=m)
    ax.set_xlabel("relearning steps on unrelated data")
    ax.set_ylabel("canary extraction rate")
    ax.set_ylim(-0.05, 1.05)
    ax.set_title("relearning attack after unlearning")
    ax.legend(fontsize=7)
    fig.tight_layout()
    fig.savefig(out / "relearn-curve.png", metadata=META)
    plt.close(fig)


def gap_curve(a: dict[str, Any], out: Path) -> None:
    s71 = next((s for s in a["strategies"] if s["id"] == "7.1"), None)
    if not s71 or not s71.get("detail", {}).get("curve"):
        return
    curve = s71["detail"]["curve"]
    fig, ax = plt.subplots(figsize=(5.6, 3.4), dpi=100)
    ax.plot(
        [c["fraction_before_capture"] for c in curve],
        [c["survival_rate"] for c in curve],
        marker="o",
    )
    ax.set_xlabel("fraction of corpus ingested before capture")
    ax.set_ylabel("subjects with a canary still retrievable")
    ax.set_ylim(-0.05, 1.05)
    ax.set_title("lineage gap: residue vs pre-capture fraction")
    fig.tight_layout()
    fig.savefig(out / "lineage-gap-curve.png", metadata=META)
    plt.close(fig)


def make(out: Path) -> list[Path]:
    out.mkdir(parents=True, exist_ok=True)
    r, u, a = _load("residue"), _load("unlearn"), _load("attacks")
    if r:
        residue_by_layer(r, out)
        drift_vs_control(r, out)
        wall_clock(r, u, out)
    if u:
        unlearn_tradeoff(u, out)
        relearn_curve(u, out)
    if a:
        gap_curve(a, out)
    return sorted(out.glob("*.png"))


def main(argv: list[str] | None = None) -> int:
    ap = argparse.ArgumentParser()
    ap.add_argument("--check", action="store_true")
    ns = ap.parse_args(argv)
    if ns.check:
        with tempfile.TemporaryDirectory() as tmp:
            fresh = make(Path(tmp))
            bad = [
                p.name
                for p in fresh
                if not (OUT / p.name).is_file() or (OUT / p.name).read_bytes() != p.read_bytes()
            ]
            print("plots byte-identical" if not bad else f"plots DIFFER: {bad}", file=sys.stderr)
            return 1 if bad else 0
    for p in make(OUT):
        print(p, file=sys.stderr)
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
